class FakeClock:
    """A clock the tests move by hand."""

    def __init__(self):
        self.now = 0.0

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds


class Charger:
    """An action that counts how often it really runs."""

    def __init__(self):
        self.calls = 0

    def __call__(self):
        self.calls += 1
        return {"charged": self.calls}


def make_store(ttl=60):
    clock = FakeClock()
    return IdempotencyStore(ttl=ttl, clock=clock), clock


def raises(error_type, function, *arguments):
    try:
        function(*arguments)
    except error_type:
        return True
    except Exception as error:
        raise AssertionError(f"expected {error_type.__name__}, got {type(error).__name__}: {error}")
    raise AssertionError(f"expected {error_type.__name__} to be raised, but the call returned normally")

