import copy
import time


class IdempotencyConflict(Exception):
    """Raised when a key that is still remembered is reused for a different request."""


class IdempotencyStore:
    def __init__(self, ttl, clock=time.monotonic):
        self.ttl = ttl
        self.clock = clock
        self._seen = {}                  # key -> (expires_at, the request as it was, the response)

    def run(self, key, request, action):
        now = self.clock()
        entry = self._seen.get(key)
        if entry is not None and now < entry[0]:
            _, first_request, response = entry
            if request != first_request:
                raise IdempotencyConflict(f"key {key!r} was already used for a different request")
            return response              # a retry: replay the first response
        response = action()              # if this raises, nothing has been stored yet
        self._seen[key] = (now + self.ttl, copy.deepcopy(request), response)   # a copy: the caller may edit their dict
        return response
